export {
  Rating,
  type RatingLabels,
  type RatingProps,
  type RatingSize,
} from "./rating"

import type { CSSProperties, ReactNode } from "react"
import { variants } from "../lib/utils/variants"

export type RatingSize = "sm" | "md" | "lg"

export interface RatingLabels {
  /** Accessible summary of the value, e.g. "4.6 out of 5 stars". */
  summary?: (value: string, max: number) => string
  /** Appended to the summary when `count` is set, e.g. "1,284 reviews". */
  reviews?: (count: number, formatted: string) => string
  /** Name of each choice in input mode, e.g. "4 stars". */
  option?: (value: number, max: number) => string
  /** Legend of the radio group in input mode. */
  group?: string
  /** Visible button that resets the value when `clearable`. */
  clear?: string
}

/*
 * Shared by display and input: --_size sets the star size, the root's mode and size pick it.
 * Stars are graphite by default (a rating is information, not a warning); --kg-rating-color
 * re-tones them per brand.
 */
export const ratingVariants = variants({
  base: [
    "kg-rating group/rating inline-flex items-center gap-1.5 align-middle leading-none text-kg-fg-muted",
    "[--_color:var(--kg-rating-color,var(--kg-fg))] [--_empty:color-mix(in_oklab,var(--kg-fg)_25%,transparent)] [--_gap:0.125em]",
  ],
  variants: {
    mode: {
      display: "",
      input: "m-0 min-w-0 border-0 p-0 [--_gap:0.0625em] disabled:opacity-50",
    },
    size: {
      sm: "text-kg-xs",
      md: "text-kg-sm",
      lg: "text-kg-base",
    },
  },
  compound: [
    { mode: "display", size: "sm", class: "[--_size:0.875rem]" },
    { mode: "display", size: "md", class: "[--_size:1.125rem]" },
    { mode: "display", size: "lg", class: "[--_size:1.5rem]" },
    { mode: "input", size: "sm", class: "[--_size:1.25rem]" },
    { mode: "input", size: "md", class: "[--_size:1.625rem]" },
    { mode: "input", size: "lg", class: "[--_size:2.125rem]" },
  ],
  defaults: { mode: "display", size: "md" },
})

export const starsClass = "kg-rating__stars inline-flex gap-(--_gap) text-(length:--_size)"

export const resolveRatingLabels = (
  labels: RatingLabels | undefined,
  locale: string | undefined,
): Required<RatingLabels> => {
  const plural = new Intl.PluralRules(locale)
  return {
    summary: (value, max) => `${value} out of ${max} stars`,
    reviews: (count, formatted) =>
      `${formatted} ${plural.select(count) === "one" ? "review" : "reviews"}`,
    option: (value) => `${value} ${value === 1 ? "star" : "stars"}`,
    group: "Rating",
    clear: "Clear",
    ...labels,
  }
}

export const DefaultStarIcon = () => (
  <svg
    viewBox="0 0 24 24"
    fill="currentColor"
    stroke="currentColor"
    strokeWidth="1.5"
    strokeLinejoin="round"
    aria-hidden="true"
    focusable="false"
  >
    <path d="M12 2.1l2.59 6.94 7.4.32-5.81 4.6 1.99 7.14L12 17l-6.17 4.1 1.99-7.14-5.81-4.6 7.4-.32z" />
  </svg>
)

interface RatingGlyphProps {
  /** 0–1: how much of this glyph is filled. */
  fill: number
  icon?: ReactNode
  preview?: boolean
  children?: ReactNode
}

/** One star: an empty glyph with a filled copy clipped to `fill`, so fractions need no extra art. */
export const RatingGlyph = ({ fill, icon, preview, children }: RatingGlyphProps) => {
  const glyph = icon ?? <DefaultStarIcon />
  const percent = Math.round(fill * 1000) / 10
  return (
    <span
      className={[
        "kg-rating__glyph relative inline-grid size-[1em] shrink-0 rounded-kg-xs transition-[scale] duration-(--kg-duration-base) ease-kg-out [&_svg]:size-full",
        "group-data-[mode=input]/rating:size-[1.125em] group-data-[mode=input]/rating:p-[0.0625em]",
        "group-data-[mode=input]/rating:data-preview:scale-[1.14]",
        "group-data-[mode=input]/rating:has-[input:focus-visible]:outline-2 group-data-[mode=input]/rating:has-[input:focus-visible]:outline-offset-1 group-data-[mode=input]/rating:has-[input:focus-visible]:outline-kg-ring",
        "group-data-touched/rating:has-[input:checked]:animate-[kg-rating-pop_var(--kg-duration-slow)_var(--kg-ease-out)]",
      ].join(" ")}
      data-fill={fill >= 1 ? "full" : fill > 0 ? "partial" : "empty"}
      data-preview={preview || undefined}
      style={
        {
          "--_fill": `${percent}%`,
          "--_clip": `inset(0 ${100 - percent}% 0 0)`,
          "--_clip-rtl": `inset(0 0 0 ${100 - percent}%)`,
        } as CSSProperties
      }
    >
      <span className="kg-rating__empty grid text-(--_empty) [grid-area:1/1]" aria-hidden="true">
        {glyph}
      </span>
      <span
        className="kg-rating__filled grid text-(--_color) [grid-area:1/1] [clip-path:var(--_clip)] rtl:[clip-path:var(--_clip-rtl)] group-data-[mode=input]/rating:transition-[clip-path] group-data-[mode=input]/rating:duration-(--kg-duration-fast) group-data-[mode=input]/rating:ease-kg-out"
        aria-hidden="true"
      >
        {glyph}
      </span>
      {children}
    </span>
  )
}

"use client"

import {
  type FieldsetHTMLAttributes,
  forwardRef,
  type KeyboardEvent,
  type ReactNode,
  useId,
  useState,
} from "react"
import { useControllableState } from "../lib/hooks/use-controllable-state"
import { useLocale } from "../lib/hooks/use-locale"
import { cx } from "../lib/utils/cx"
import { clamp } from "../lib/utils/math"
import {
  RatingGlyph,
  type RatingLabels,
  type RatingSize,
  ratingVariants,
  resolveRatingLabels,
  starsClass,
} from "./rating-glyph"

export interface RatingInputProps extends Omit<
  FieldsetHTMLAttributes<HTMLFieldSetElement>,
  "defaultValue" | "onChange"
> {
  value?: number | undefined
  defaultValue?: number | undefined
  onValueChange?: ((value: number) => void) | undefined
  max: number
  precision: 0.5 | 1
  size: RatingSize
  icon?: ReactNode
  clearable: boolean
  required?: boolean | undefined
  label?: string | undefined
  locale?: string | undefined
  labels?: RatingLabels | undefined
}

export const RatingInput = forwardRef<HTMLFieldSetElement, RatingInputProps>(
  (
    {
      value: valueProp,
      defaultValue = 0,
      onValueChange,
      max,
      precision,
      size,
      icon,
      clearable,
      required,
      label,
      locale,
      labels,
      name,
      disabled,
      className,
      onKeyDown,
      ...props
    },
    ref,
  ) => {
    const [value, setValue] = useControllableState({
      value: valueProp,
      defaultValue,
      onChange: onValueChange,
    })
    const [hover, setHover] = useState<number | null>(null)
    const [touched, setTouched] = useState(false)
    const autoName = useId()
    const groupName = name ?? autoName
    const resolvedLocale = useLocale(locale)
    const text = resolveRatingLabels(labels, resolvedLocale)
    const shown = hover ?? value
    const steps = precision === 0.5 ? [0.5, 1] : [1]
    const previewIndex = hover === null ? -1 : Math.ceil(hover) - 1

    const select = (next: number) => {
      setTouched(true)
      setValue(next)
    }

    const handleKeyDown = (event: KeyboardEvent<HTMLFieldSetElement>) => {
      onKeyDown?.(event)
      if (event.defaultPrevented || !clearable) return
      if (event.key === "Backspace" || event.key === "Delete") {
        event.preventDefault()
        select(0)
      }
    }

    return (
      <fieldset
        ref={ref}
        className={ratingVariants({ mode: "input", size, className })}
        data-mode="input"
        data-size={size}
        data-touched={touched || undefined}
        disabled={disabled}
        onKeyDown={handleKeyDown}
        {...props}
      >
        <legend className="kg-visually-hidden">{label ?? text.group}</legend>
        <span className={starsClass} onPointerLeave={() => setHover(null)}>
          {Array.from({ length: max }, (_, index) => (
            <RatingGlyph
              key={index}
              fill={clamp(shown - index, 0, 1)}
              icon={icon}
              preview={index === previewIndex}
            >
              {steps.map((step) => {
                const option = index + step
                return (
                  <label
                    key={option}
                    className={cx(
                      "kg-rating__hit absolute inset-y-0 group-enabled/rating:cursor-pointer",
                      step === 1 && steps.length === 2 ? "start-1/2 end-0" : steps.length === 2 ? "start-0 end-1/2" : "inset-x-0",
                    )}
                    data-part={
                      steps.length === 1 ? "full" : step === 1 ? "end" : "start"
                    }
                    onPointerEnter={(event) => {
                      if (event.pointerType === "mouse") setHover(option)
                    }}
                  >
                    <input
                      type="radio"
                      className="kg-rating__radio absolute inset-0 m-0 size-full cursor-[inherit] opacity-0"
                      name={groupName}
                      value={option}
                      checked={value === option}
                      required={required}
                      onChange={() => select(option)}
                      onClick={() => {
                        // Clicking the chosen star again is the familiar way to clear a rating.
                        if (clearable && value === option) select(0)
                      }}
                    />
                    <span className="kg-visually-hidden">
                      {text.option(option, max)}
                    </span>
                  </label>
                )
              })}
            </RatingGlyph>
          ))}
        </span>
        {clearable && (
          <button
            type="button"
            className="kg-rating__clear cursor-pointer rounded-kg-xs border-0 bg-transparent px-1.5 py-1 font-[inherit] text-kg-xs font-[550] text-kg-fg-muted transition-[opacity] duration-(--kg-duration-fast) ease-kg-out hover:text-kg-fg hover:underline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-kg-ring data-hidden:invisible data-hidden:opacity-0"
            data-hidden={value === 0 || undefined}
            tabIndex={value === 0 ? -1 : undefined}
            aria-hidden={value === 0 || undefined}
            onClick={() => select(0)}
          >
            {text.clear}
          </button>
        )}
      </fieldset>
    )
  },
)

RatingInput.displayName = "RatingInput"

"use client"

import { forwardRef, type HTMLAttributes, type ReactNode, type Ref } from "react"
import { useLocale } from "../lib/hooks/use-locale"
import { clamp, roundToStep } from "../lib/utils/math"
import {
  RatingGlyph,
  type RatingLabels,
  type RatingSize,
  ratingVariants,
  resolveRatingLabels,
  starsClass,
} from "./rating-glyph"
import { RatingInput } from "./rating-input"

export type { RatingLabels, RatingSize }

export interface RatingProps extends Omit<
  HTMLAttributes<HTMLElement>,
  "defaultValue" | "onChange"
> {
  /** The rating. In display mode this is the average, e.g. 4.6. */
  value?: number
  /** Initial value for an uncontrolled input. */
  defaultValue?: number
  /** Turns the rating into an input (a radio group). */
  onValueChange?: (value: number) => void
  /** Render as an input without a change handler, e.g. an uncontrolled form field with `name`. */
  interactive?: boolean
  max?: number
  /**
   * Display mode: the fill is rounded to this step (default 0.1).
   * Input mode: 1 (whole stars, default) or 0.5 (half stars).
   */
  precision?: number
  size?: RatingSize
  /** Number of reviews, shown as "(1,284)" after the stars. */
  count?: number
  /** Turns the stars and count into a link, usually to the reviews section. */
  href?: string
  /** Show the numeric value next to the stars. */
  showValue?: boolean
  /** Replaces the star. It should paint with `currentColor`. */
  icon?: ReactNode
  /** Input mode: allow clearing back to 0 (click the chosen star, Delete, or the Clear button). */
  clearable?: boolean
  required?: boolean
  disabled?: boolean
  readOnly?: boolean
  name?: string
  /** Input mode: the group's accessible name (defaults to `labels.group`). */
  label?: string
  locale?: string
  labels?: RatingLabels
}

/**
 * Star rating. Without `onValueChange` it is a server-safe display; with it, a native radio group
 * with arrow-key selection and hover preview.
 */
export const Rating = forwardRef<HTMLElement, RatingProps>(
  (
    {
      value,
      defaultValue,
      onValueChange,
      interactive = false,
      max = 5,
      precision,
      size = "md",
      count,
      href,
      showValue = false,
      icon,
      clearable = false,
      required,
      disabled,
      readOnly = false,
      name,
      label,
      locale,
      labels,
      className,
      ...props
    },
    ref,
  ) => {
    const resolvedLocale = useLocale(locale)
    if (!readOnly && (onValueChange !== undefined || interactive)) {
      return (
        <RatingInput
          ref={ref as Ref<HTMLFieldSetElement>}
          value={value}
          defaultValue={defaultValue}
          onValueChange={onValueChange}
          max={max}
          precision={precision === 0.5 ? 0.5 : 1}
          size={size}
          icon={icon}
          clearable={clearable}
          required={required}
          disabled={disabled}
          name={name}
          label={label}
          locale={locale}
          labels={labels}
          className={className}
          {...(props as Omit<
            HTMLAttributes<HTMLFieldSetElement>,
            "defaultValue" | "onChange"
          >)}
        />
      )
    }

    const text = resolveRatingLabels(labels, resolvedLocale)
    const current = clamp(value ?? defaultValue ?? 0, 0, max)
    const filled = roundToStep(current, precision ?? 0.1)
    const valueText = new Intl.NumberFormat(resolvedLocale, {
      maximumFractionDigits: 1,
    }).format(current)
    const countText =
      count === undefined ? undefined : new Intl.NumberFormat(resolvedLocale).format(count)
    const summary =
      text.summary(valueText, max) +
      (count === undefined || countText === undefined
        ? ""
        : `, ${text.reviews(count, countText)}`)

    const content = (
      <>
        <span className="kg-visually-hidden">{summary}</span>
        <span className={starsClass} aria-hidden="true">
          {Array.from({ length: max }, (_, index) => (
            <RatingGlyph key={index} fill={clamp(filled - index, 0, 1)} icon={icon} />
          ))}
        </span>
        {showValue && (
          <span className="kg-rating__value font-[650] text-kg-fg tabular-nums" aria-hidden="true">
            {valueText}
          </span>
        )}
        {countText !== undefined && (
          <span
            className="kg-rating__count tabular-nums group-hover/link:text-kg-fg group-hover/link:underline group-hover/link:underline-offset-[0.2em]"
            aria-hidden="true"
          >
            ({countText})
          </span>
        )}
      </>
    )

    return (
      <span
        ref={ref as Ref<HTMLSpanElement>}
        className={ratingVariants({ mode: "display", size, className })}
        data-mode="display"
        data-size={size}
        {...props}
      >
        {href ? (
          <a
            className="kg-rating__link group/link inline-flex items-center gap-[inherit] rounded-kg-xs text-inherit no-underline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-kg-ring"
            href={href}
          >
            {content}
          </a>
        ) : (
          content
        )}
      </span>
    )
  },
)

Rating.displayName = "Rating"
